#!/usr/bin/env python3
"""Modern climate data analysis script."""

import configparser
from pathlib import Path

import numpy as np
import pandas as pd


def load_temperature_data(filepath: Path) -> pd.DataFrame:
    df = pd.read_csv(filepath, encoding="utf-8", parse_dates=["date"])
    return df


def calculate_mean_temperatures(df: pd.DataFrame) -> pd.Series:
    return df.groupby("station_id")["temperature"].mean()


def run_analysis(
    csv_path: Path | None = None,
    config_path: Path | None = None,
) -> None:
    if config_path is None:
        config_path = Path("config.ini")

    cfg = configparser.ConfigParser()
    if config_path.exists():
        cfg.read(config_path, encoding="utf-8")

    if csv_path is None:
        csv_path = Path("climate_analyzer/sample_data/climate_data.csv")

    data = load_temperature_data(csv_path)
    means = calculate_mean_temperatures(data)

    for station_id, mean_temp in means.items():
        print(f"Station {station_id} mean temperature: {mean_temp:.1f}°C")


if __name__ == "__main__":
    run_analysis()

